-- MKT-002: all fixtures run inside the guarded policy runner rollback transaction.
RESET ROLE;
CREATE TABLE firstten_policy_test.marketing_docs(label text PRIMARY KEY,doc jsonb NOT NULL);
CREATE TABLE firstten_policy_test.marketing_results(label text PRIMARY KEY,result jsonb NOT NULL);
GRANT SELECT ON firstten_policy_test.marketing_docs TO authenticated,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON firstten_policy_test.marketing_results TO authenticated;
