CREATE FUNCTION firstten_policy_test.marketing_doc() RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT document FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a') $$;
CREATE FUNCTION firstten_policy_test.marketing_save(doc jsonb,complete boolean DEFAULT false) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path=pg_catalog AS $$ SELECT public.save_marketing_plan(firstten_policy_test.id('project_a'),coalesce((SELECT revision FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a')),0),gen_random_uuid(),complete,doc) $$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.marketing_doc(),firstten_policy_test.marketing_save(jsonb,boolean) TO authenticated;
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.marketing_plans'::regclass),'marketing table RLS enabled');
SELECT ok((SELECT prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] FROM pg_proc WHERE oid='public.save_marketing_plan(uuid,bigint,uuid,boolean,jsonb)'::regprocedure),'save RPC has fixed search path and narrow definer authority');
SELECT ok(NOT has_function_privilege('anon','public.save_marketing_plan(uuid,bigint,uuid,boolean,jsonb)','EXECUTE'),'anonymous cannot execute save RPC');
SELECT ok(NOT has_function_privilege('service_role','public.save_marketing_plan(uuid,bigint,uuid,boolean,jsonb)','EXECUTE'),'service role has no save shortcut');
SELECT ok(NOT has_table_privilege('authenticated','public.marketing_plans','INSERT,UPDATE,DELETE'),'authenticated has no direct plan mutation grant');
SELECT ok(NOT has_table_privilege('service_role','public.marketing_plans','SELECT,INSERT,UPDATE,DELETE'),'service role has no direct plan shortcut');
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
SELECT is(firstten_policy_test.marketing_save((SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'))->>'code','STAGE_LOCKED','stage 1 cannot create');
UPDATE public.projects SET stage=2 WHERE id IN (firstten_policy_test.id('project_a'),firstten_policy_test.id('project_a2'));
INSERT INTO firstten_policy_test.marketing_results SELECT 'created',public.save_marketing_plan(firstten_policy_test.id('project_a'),0,'f4000000-0000-4000-8000-000000000100',false,jsonb_set(jsonb_set(doc,'{schemaVersion}','1.0'),'{resources,cashBudgetCents}','0.0')) FROM firstten_policy_test.marketing_docs WHERE label='empty';
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.marketing_results WHERE label='created'),'true','owner creates empty private plan');
SELECT is((SELECT revision FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a')),1::bigint,'first save starts at revision 1');
SELECT is(firstten_policy_test.marketing_doc()#>'{test,target}','null'::jsonb,'unknown target stays null');
SELECT is(firstten_policy_test.marketing_doc()->>'schemaVersion','1','decimal schema constant is stored canonically');
SELECT is(firstten_policy_test.marketing_doc()#>>'{resources,cashBudgetCents}','0','decimal zero budget is stored canonically');
SELECT is(firstten_policy_test.marketing_doc()#>'{studentFirst,completedAt}','null'::jsonb,'empty board has no fabricated completion');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),0,'f4000000-0000-4000-8000-000000000100',false,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty')),(SELECT result FROM firstten_policy_test.marketing_results WHERE label='created'),'integer retry of decimal-valued constants returns the same acknowledgement');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),0,'f4000000-0000-4000-8000-000000000100',false,jsonb_set(firstten_policy_test.marketing_doc(),'{audience,beachhead}','"  "'))->>'ok','true','canonical whitespace normalization supports identical retry');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),0,'f4000000-0000-4000-8000-000000000100',false,jsonb_set(jsonb_set((SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'),'{schemaVersion}','1.000'),'{resources,cashBudgetCents}','0.00')),(SELECT result FROM firstten_policy_test.marketing_results WHERE label='created'),'equivalent decimal spellings replay the same saved revision');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),0,'f4000000-0000-4000-8000-000000000100',false,jsonb_set(firstten_policy_test.marketing_doc(),'{audience,beachhead}','"changed"'))->>'code','IDEMPOTENCY_CONFLICT','same token cannot carry changed content');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),1,'f4000000-0000-4000-8000-000000000100',false,firstten_policy_test.marketing_doc())->>'code','IDEMPOTENCY_CONFLICT','expected revision is included in replay hash');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),0,gen_random_uuid(),false,firstten_policy_test.marketing_doc())->>'code','CONFLICT','create-only never overwrites existing plan');
SELECT is(firstten_policy_test.marketing_save(firstten_policy_test.marketing_doc(),true)->>'code','INVALID_PLAN','incomplete first board cannot complete');
SELECT is(firstten_policy_test.attempt($case$UPDATE public.marketing_plans SET revision=99$case$),'error:42501','direct revision tampering denied');
SELECT is(firstten_policy_test.attempt($case$DELETE FROM public.marketing_plans$case$),'error:42501','direct plan deletion denied');
SELECT is(firstten_policy_test.attempt($case$INSERT INTO public.marketing_plans(project_id,document,last_mutation_id,last_mutation_hash) VALUES(firstten_policy_test.id('project_a2'),'{}',gen_random_uuid(),repeat('a',64))$case$),'error:42501','direct inserts cannot bypass RPC');
RESET ROLE;
SELECT firstten_policy_test.set_actor('owner_b');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a')),0::bigint,'owner_b cannot read owner A plan');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),1,gen_random_uuid(),false,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'))->>'code','NOT_FOUND','owner_b cannot forge owner A scope');
RESET ROLE;
