SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),1,gen_random_uuid(),false,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'))->>'code','NOT_FOUND','viewer cannot forge owner A scope');
RESET ROLE;
