SELECT firstten_policy_test.set_actor('admin');
SET LOCAL ROLE authenticated;
SELECT is((SELECT count(*) FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a')),0::bigint,'admin cannot read owner A plan');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),1,gen_random_uuid(),false,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'))->>'code','NOT_FOUND','admin cannot forge owner A scope');
