SET LOCAL ROLE authenticated;
UPDATE public.projects SET stage=2 WHERE id=firstten_policy_test.id('project_b');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_b'),0,gen_random_uuid(),false,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'))->>'ok','true','second owner independently creates its own plan');
SELECT is((SELECT count(*) FROM public.marketing_plans),1::bigint,'second owner sees only its own plan');
RESET ROLE;
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE anon;
SELECT is(firstten_policy_test.attempt($case$SELECT * FROM public.marketing_plans$case$),'error:42501','anonymous plan read denied');
SELECT is(firstten_policy_test.attempt($case$SELECT public.save_marketing_plan(firstten_policy_test.id('project_a'),1,gen_random_uuid(),false,'{}')$case$),'error:42501','anonymous save denied');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','',true),set_config('request.jwt.claims','{}',true);
SET LOCAL ROLE authenticated;
SELECT is(public.save_marketing_plan('f4000000-0000-4000-8000-000000000999',0,gen_random_uuid(),false,'{}')->>'code','UNAUTHENTICATED','missing subject fails before scope lookup');
RESET ROLE;
SELECT firstten_policy_test.set_actor('owner_a');
SET LOCAL ROLE authenticated;
INSERT INTO firstten_policy_test.marketing_results SELECT 'completed',firstten_policy_test.marketing_save(jsonb_set(doc,'{studentFirst,completedAt}','"2000-01-01T00:00:00Z"'),true) FROM firstten_policy_test.marketing_docs WHERE label='rich';
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.marketing_results WHERE label='completed'),'true','valid manual first thinking completes');
SELECT ok(firstten_policy_test.marketing_doc()#>>'{studentFirst,completedAt}'<>'2000-01-01T00:00:00Z','completion timestamp is server-derived');
SELECT is(firstten_policy_test.marketing_doc()#>'{assets,0,review,truthful}','false'::jsonb,'new content cannot arrive already reviewed');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),1,(SELECT last_mutation_id FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a')),true,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='rich')),(SELECT result FROM firstten_policy_test.marketing_results WHERE label='completed'),'first completion retry ignores only server-derived completion timestamp');
SELECT is(firstten_policy_test.marketing_doc()#>>'{assets,0,walkthrough,hesitation}','Keep this dated observation','review reset retains walkthrough notes');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{studentFirst,audience}','"rewrite"'))->>'code','INVALID_PLAN','completed first board cannot be rewritten');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{studentFirst,completedAt}','null'))->>'code','INVALID_PLAN','completion cannot be cleared');
SELECT is(firstten_policy_test.marketing_save(firstten_policy_test.marketing_doc(),true)->>'code','INVALID_PLAN','ordinary saves cannot start another initial cycle');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{assets,0,review}','{"truthful":true,"disclosedBuilder":true,"accessChecked":true,"destinationChecked":true,"checkedAt":"2026-10-18T12:00:00Z"}'))->>'ok','true','stable saved content can be explicitly reviewed');
SELECT is(firstten_policy_test.marketing_doc()#>'{assets,0,review,truthful}','true'::jsonb,'unchanged content retains manual review');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{sources,0,text}','"Changed supporting observation"'))->>'ok','true','owner can revise supporting observation');
SELECT is(firstten_policy_test.marketing_doc()#>'{assets,0,review,truthful}','false'::jsonb,'changed support clears stale asset review');
INSERT INTO public.interviews(id,project_id,completed) VALUES('f4000000-0000-4000-8000-000000000200',firstten_policy_test.id('project_a2'),true);
