SELECT is(firstten_policy_test.marketing_save(firstten_policy_test.marketing_doc()-'sources')->>'code','INVALID_PLAN','reject missing key');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{assets,0,body}',to_jsonb(repeat('x',4001))))->>'code','INVALID_PLAN','reject excess text');
