SELECT is((SELECT to_jsonb(t) FROM (SELECT revision,document,history FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a'))t),(SELECT to_jsonb(t) FROM marketing_preserved t),'all invalid saves preserve current plan and history');
