DO $$ BEGIN FOR i IN 1..4 LOOP PERFORM firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{audience,situation}',to_jsonb('Revision '||i))); END LOOP; END $$;
