INSERT INTO firstten_policy_test.marketing_results SELECT 'restore',firstten_policy_test.marketing_save(history->0->'document') FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a');
SELECT is((SELECT result->>'ok' FROM firstten_policy_test.marketing_results WHERE label='restore'),'true','explicit snapshot restore is a new validated save');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),0,'f4000000-0000-4000-8000-000000000100',false,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'))->>'code','CONFLICT','old retry after later save does not replay old content');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{channels,0,access}','{"state":"allowed","rulesNote":"Owner reports permission","rulesSourceId":null,"checkedOn":"2026-10-18","nextQuestion":""}'))->>'ok','true','owner may record a dated manual permission basis');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(jsonb_set(jsonb_set(jsonb_set(firstten_policy_test.marketing_doc(),'{assets,0,review}','{"truthful":true,"disclosedBuilder":true,"accessChecked":true,"destinationChecked":true,"checkedAt":"2026-10-18T12:00:00Z"}'),'{assets,0,walkthrough}','{"mode":"self","understoodAudience":"Student founders","actionObserved":"Found the interview action","hesitation":"None observed","revisionMade":"No change","checkedOn":"2026-10-18"}'),'{test,startedAt}','"2026-10-18T12:00:00Z"'),'{test,state}','"running"'))->>'ok','true','reviewed manual plan can move to running with an actual next task');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(firstten_policy_test.marketing_doc(),'{assets,0,body}','"Changed after launch review"'))->>'code','INVALID_PLAN','running copy change cannot silently retain launch approval');
SELECT is(firstten_policy_test.marketing_save(jsonb_set(jsonb_set(firstten_policy_test.marketing_doc(),'{test,state}','"reviewed"'),'{reflection}','{"decision":"revise","evidenceIds":[],"learned":"No observations collected yet","uncertainty":"No results available","nextAction":"Investigate access","reviewedOn":"2026-10-25"}'))->>'ok','true','reflection can close a test with no positive outcome or fabricated counts');
UPDATE public.projects SET stage=1 WHERE id=firstten_policy_test.id('project_a');
SELECT is((SELECT count(*) FROM public.marketing_plans WHERE project_id=firstten_policy_test.id('project_a')),1::bigint,'owner still reads saved plan after stage downgrade');
SELECT is(firstten_policy_test.marketing_save(firstten_policy_test.marketing_doc())->>'code','STAGE_LOCKED','downgrade denies new saves without deleting plan');
SELECT is(public.save_marketing_plan(firstten_policy_test.id('project_a'),0,'f4000000-0000-4000-8000-000000000100',false,(SELECT doc FROM firstten_policy_test.marketing_docs WHERE label='empty'))->>'code','STAGE_LOCKED','stage rechecked before idempotency replay');
RESET ROLE;
